(window.TIMELINE_TRANSLATIONS=window.TIMELINE_TRANSLATIONS||{})["ie"]={"qin-dynasty":{"id":"qin-dynasty","title":"Dinastie Qin","summary":"Li state de Qin conquestat su principal rivales sub Ying Zheng, qui adoptet li imperial titul Qin Shi Huang. Li dinastie durat solmen curt témpor, ma su militari e administrativ practicas influet li sequent imperie Han.","began":"Li conquestes de Qin culminat in unification, e Ying Zheng declarat se imperator.","ended":"Li dinastie collapset in li annus pos li morte de Qin Shi Huang; concurrent potenties combatet ante que Han establisset imperial governament.","why":"It creat un imperial politic cadre quel plu tard dinasties adaptet."},"confucius":{"id":"confucius","title":"Confucio inseni etic governament","summary":"Confucio inseniat durant li periode de Printempes e Autunes. Il emfasat moral conduida, familial responsabilitás, aprension e li deve del regnator de governar per virtú. Su inseniamentes devenit un important intellectual tradition, e plu tard imperial governamentes metet confucian textus in li centre del oficial education.","why":"Su inseniamentes formet politic etica, education e familial ideales tra Ost-Asia."},"stonewall-riots":{"id":"stonewall-riots","title":"Insurection de Stonewall","summary":"Clientes e suportantes resistet un razzia policial in li Stonewall Inn in New York, sequet de ulteriori confrontationes e demonstrationes. Li insurection devenit un potent punctu de referentie por un crescent movement contra li persecution de sexual minoritás.","why":"Stonewall auxiliat energisar li gay liberation e plu tard LGBTQ organisation, sin esser li unesim acte de resistentie."}};
